var n=`0025-paska`;var i=`world-0025`;var t=`UA`;var o=`eastern-europe`;var s=10;var r=167;var l={en:`Paska`,ua:`Паска`};var u={en:`A classic dish from Ukraine, featuring whole cow milk, chicken egg, raisin. A practical home-kitchen version with measured step ingredients and clear cooking methods.`,ua:`Класична страва з Україна. Основні складники: цільне коров'яче молоко, куряче яйце, родзинки. Домашній варіант із поетапними діями та точними кількостями продуктів.`};var g=[{en:`Mix and knead into a supple yeast dough. Cover and leave in a warm place until roughly doubled, about 90 minutes.`,ua:`Змішайте й вимісіть м’яке дріжджове тісто. Накрийте та поставте в тепле місце до збільшення об’єму приблизно вдвічі, орієнтовно на 90 хвилин.`,t:[`mixing`,`kneading`,`bulk-fermentation`],m:90,i:[[`all-purpose-flour`,630,`g`],[`whole-cow-milk`,240,`ml`],[`instant-yeast`,9,`g`],[`white-granulated-sugar`,145,`g`],[`unsalted-butter`,120,`g`],[`chicken-egg`,4,`pcs`],[`raisin`,120,`g`],[`vanilla-extract`,4,`ml`],[`table-salt`,4,`g`]]},{en:`Divide and shape the dough as required. Place on a lined tray and proof for about 35 minutes while the oven heats.`,ua:`Поділіть і сформуйте тісто відповідно до виробу. Викладіть на деко з пергаментом і залиште підходити приблизно на 35 хвилин, поки гріється духовка.`,t:[`pre-shaping-dough`,`final-proofing`],m:35,i:[]},{en:`Bake in a preheated 180°C oven for about 40 minutes until set, golden and cooked through. Cool on a rack.`,ua:`Випікайте в розігрітій до 180°C духовці приблизно 40 хвилин до рум’яності та повної готовності. Остудіть на решітці.`,t:[`baking`],m:40,i:[]},{en:`Finish with the listed ingredients, check seasoning and serve immediately.`,ua:`Додайте завершальні складники, перевірте смак і відразу подавайте.`,t:[`seasoning`,`garnishing`],m:2,i:[[`powdered-sugar`,90,`g`],[`lemon-juice`,15,`ml`]]}];var d={slug:n,id:i,country:`UA`,region:o,servings:10,minutes:167,title:l,text:u,steps:g};export{t as country,d as default,i as id,r as minutes,o as region,s as servings,n as slug,g as steps,u as text,l as title};